# Sourced by the role scripts, which run as root inside the VMs.
# lab.sh provision copies this, the role script and role-env.sh (generated per VM) to /tmp/fs-stress.
# Exit code 100 from a role script means "reboot me and run me again".
# shellcheck shell=bash
set -euo pipefail
# shellcheck source=/dev/null # generated by lab.sh provision
source /tmp/fs-stress/role-env.sh

NEED_REBOOT=100

log() { echo "[$(hostname -s)] $*"; }

base_setup() {
  [[ -f /etc/fs-stress-base-done ]] && return
  log "base setup"
  # Stay on 9.7: $releasever=9 would pull 9.8, whose kernels Lustre doesn't support.
  # shellcheck disable=SC2016 # dnf variables, not shell ones
  sed -i -e 's/^mirrorlist=/#mirrorlist=/' \
    -e 's|^#baseurl=http://dl.rockylinux.org/$contentdir/$releasever|baseurl=https://dl.rockylinux.org/vault/rocky/9.7|' \
    /etc/yum.repos.d/rocky*.repo
  # Throwaway test VMs; Lustre and BeeGFS both want SELinux off.
  setenforce 0 || true
  sed -i 's/^SELINUX=.*/SELINUX=permissive/' /etc/selinux/config
  systemctl disable --now firewalld 2>/dev/null || true
  dnf install -y dnf-plugins-core
  touch /etc/fs-stress-base-done
}

# Boot into the given kernel version, installing the listed packages for it first.
ensure_kernel() { # ensure_kernel <version> <pkg...>
  local ver=$1
  shift
  [[ $(uname -r) == "$ver.x86_64" ]] && return
  log "installing kernel $ver"
  dnf install -y "${@/%/-$ver}"
  grubby --set-default "/boot/vmlinuz-$ver.x86_64"
  exit $NEED_REBOOT
}

enable_epel() {
  rpm -q epel-release &>/dev/null && return
  dnf config-manager --set-enabled crb
  dnf install -y epel-release
}

data_disk() { readlink -f "/dev/disk/by-id/virtio-data$1"; }

primary_iface() { ip -o route get 1.1.1.1 | sed -n 's/.* dev \([^ ]*\).*/\1/p'; }

lnet_config() {
  echo "options lnet networks=tcp0($(primary_iface))" >/etc/modprobe.d/lustre.conf
}

fstab_line() { # fstab_line <mountpoint> <full line>: add or replace
  sed -i "\\| $1 |d" /etc/fstab
  echo "$2" >>/etc/fstab
  systemctl daemon-reload
}

# Mount an fstab entry through its systemd unit, not mount(8): a FUSE daemon started by
# mount(8) here would live in provision's ssh session, which systemd stops at shutdown
# before unmounting, waiting 90 s and then killing the daemon under its mount.
mount_fstab() { # mount_fstab <mountpoint>
  mountpoint -q "$1" || systemctl start "$(systemd-escape -p --suffix=mount "$1")"
}

# IBM Storage Scale (GPFS), shared by gpfs-srv and the clients.
SCALE_DIR=/var/tmp/fs-stress-scale
export PATH=/usr/lpp/mmfs/bin:$PATH

# Install Storage Scale from the zip lab.sh provision --scale-installer uploaded, and build the
# portability layer (kernel module) for the running kernel.
install_gpfs() {
  dnf install -y cpp gcc gcc-c++ make binutils elfutils-libelf-devel ksh m4
  if ! rpm -q gpfs.base &>/dev/null; then
    local zip=$SCALE_DIR/Storage_Scale_installer.zip
    [[ -f $zip ]] || {
      log "Storage Scale isn't installed and no installer was uploaded."
      log "Download the Developer Edition zip from IBM and run:"
      log "  lab.sh provision --scale-installer <zip> $(hostname -s)"
      exit 1
    }
    log "installing Storage Scale"
    dnf install -y unzip
    rm -rf "$SCALE_DIR/x"
    (cd "$SCALE_DIR" && unzip -o -q "$zip" && md5sum -c ./*-install.md5)
    # --silent accepts IBM's license (the Developer Edition one you agreed to when downloading).
    bash "$(compgen -G "$SCALE_DIR/Storage_Scale_*-install" | head -1)" --silent --dir "$SCALE_DIR/x" >/dev/null
    local r=$SCALE_DIR/x/gpfs_rpms
    dnf install -y "$r"/gpfs.{base,gpl,gskit,msg.en_US,license.dev,adv,compression}-*.rpm
    rm -rf "$SCALE_DIR"
  fi
  [[ -f /lib/modules/$(uname -r)/extra/mmfs26.ko ]] || mmbuildgpl
}

# GPFS wants every node name to resolve to the same real address on every node (never
# loopback), so pin them all in /etc/hosts rather than rely on dnsmasq.
gpfs_hosts() {
  local entry name
  for entry in $GPFS_NODES; do
    name=${entry%%:*}
    sed -i "/ $name\$/d" /etc/hosts
    echo "${entry#*:} $name.fs-stress $name" >>/etc/hosts
  done
}

gpfs_state() { mmgetstate -Y | awk -F: 'NR > 1 { print $9 }'; }
